#!/bin/bash
agent-browser --session z2953-h5 eval --stdin <<'EOF'
location.href = 'http://unlimited.c.h5-zhishu.shimin.mobile.v2.suzhufang.shiqu.suzhou.test.zhi.com/pages/project-check/records/index?checkType=1&from=handheld&complexId=667585159348728&complexName=%E5%98%89%E6%A8%BE%E6%97%B6%E4%BB%A3%E8%8A%B1%E5%9B%AD';
'navigated'
EOF

$hostsPath = 'C:\Windows\System32\drivers\etc\hosts'
$entry = '192.168.1.31 unlimited.c.h5-zhishu.shimin.mobile.v2.suzhufang.shiqu.suzhou.test.zhi.com'
$lines = Get-Content $hostsPath
if ($lines -match [regex]::Escape($entry)) {
  Write-Output 'ALREADY_PRESENT'
} else {
  Add-Content -Path $hostsPath -Value "`n# z2953 H5 verification (temporary, remove after verify)`n$entry" -Encoding UTF8
  Write-Output 'ADDED'
}
ipconfig /flushdns | Out-Null
Write-Output 'DNS_FLUSHED'
Select-String -Path $hostsPath -Pattern 'h5-zhishu' | ForEach-Object { $_.Line }

