tool_input.command:
powershell -NoProfile -Command "
\$paths = @('HKLM:\SOFTWARE\Policies\Microsoft\Edge','HKCU:\SOFTWARE\Policies\Microsoft\Edge','HKLM:\SOFTWARE\Policies\Google\Chrome','HKCU:\SOFTWARE\Policies\Google\Chrome')
foreach (\$p in \$paths) {
  if (Test-Path \$p) {
    \$props = Get-ItemProperty \$p
    \$props.PSObject.Properties | Where-Object { \$_.Name -match 'Block|Allow|URL|DNS|Secure' } | ForEach-Object { \"\$p :: \$(\$_.Name) = \$(\$_.Value)\" }
  }
}
'---extensions---'
Get-ChildItem 'C:\Users\ADMINI~1\AppData\Local\Temp\agent-browser-chrome-*' -Directory -ErrorAction SilentlyContinue | ForEach-Object { \$e=Join-Path \$_.FullName 'Default\Extensions'; if(Test-Path \$e){ Get-ChildItem \$e -Directory | Select-Object -ExpandProperty Name } }
" 2>&1 | head -40
